typedef state_t (*trans_t)(fsm_t *f, char ch);
static trans_t const table[STATE_COUNT][EVENT_COUNT];

state_t run(fsm_t *f, char ch)
{
    trans_t next = table[f->state][classify(ch)];
    return next(f, ch);
}

